window.RP_SESSION={"id":"S-66fd5ba99930","messages":[{"id":"RP-0197091","time":"2026-07-20T23:14:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"죽은 자는 죽은대로 있어야 한다.\n\n그것이 약속이자. 이름이 존재하는 이유이며. 서명이다.\n\n우리는 기억해야 한다, 죽은 자의 과거를. 다만 그것을 멋대로 곡해해서는 안되며, 있는 그대로를 인용함으로서. \n\n최대한 존재의 이야기를 원형 그대로 추모해야 한다.\n\n그러나 우리는 그럼에도 인간이기에, 결국 기억이란 이름으로 이야기를 곡해하게 되고 마는 것이다.\n\n따라서 끝마쳐진, 이내 시간이 지나 곡해된 이야기가 되살아난다는 것은, 결국 이름의 의미를 해치는 것이 된다.\n\n보라. 되살아난 자, 재구축된 자가 정말 그 본인일까?\n\n아니면 끝마쳐진 삶에 대한 억지에 불과할까?","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197092","time":"2026-07-20T23:15:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"부활이 죽었던 이름을 그대로 이어받는 것은, 옳은가?","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197093","time":"2026-07-20T23:16:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"진저는 진저인가? 테론은 테론인가?","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197094","time":"2026-07-20T23:16:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"만약 나의 어머니가 지금 무덤을 박차고 일어나신다면, 그것은 어머니인가?","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197095","time":"2026-07-20T23:16:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"사랑하던 어머니, 나의 가여운 어머니.","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197096","time":"2026-07-20T23:17:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그리고 어머니의 허무한 끝을 추모하고, 그 몫까지 살아가려 애쓰는 나.","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197097","time":"2026-07-20T23:17:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그야 그것이 최선이니까.","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197098","time":"2026-07-20T23:17:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그리고, 그리고... 계속해서 반복되어 이어지는 그리고...","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197099","time":"2026-07-20T23:18:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그리고... 너는, 뭐야?","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197100","time":"2026-07-20T23:18:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"너는 마리아인거야?","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197101","time":"2026-07-20T23:20:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"아니, 이 표현은 틀렸어.","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197102","time":"2026-07-20T23:20:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"마리아가 너야?","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197103","time":"2026-07-20T23:20:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그렇게 그녀의 방... 이었던 곳을 쳐다보다가.","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197104","time":"2026-07-20T23:20:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"이내 돌아섰다.","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197105","time":"2026-07-20T23:20:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"찾아서, 증명을 요구하기로 했다.","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197106","time":"2026-07-20T23:21:00+09:00","room":"RP","name":"아이다","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-8208f1c7d9cb"]},{"id":"RP-0197107","time":"2026-07-20T23:21:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
